const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const p = text => `<p>${text}</p>`;
const code = text => `<div class="codeblock"><div class="codebar"><span>Синтетический пример</span><button class="copy">Копировать</button></div><pre><code>${esc(text)}</code></pre></div>`;
const section = (id, title, body) => ({ id, title, body });
const link = (id, title) => `<a href="#/article/${id}">${title} →</a>`;
const note = (title, text) => `<div class="callout warning"><strong>${title}</strong>${p(text)}</div>`;
const doc = (id, title, lead, status, sections, sources) => ({ id, title, lead, status, group: 'Разработка через файлы', time: '7 мин', sections, sources });
const pm = 'https://elma365.com/ru/help/platform/lowcode-devops-pm.html';
const exchange = 'https://elma365.com/ru/help/platform/export-import-elma365.html';
const official = `<a href="${pm}" rel="noreferrer">Справка elma365pm</a>`;
export const developerArticles = [
  doc('file-development', 'Разработка ELMA365 через файлы', 'Найти сущность → изменить JSON и TypeScript → проверить связи → перенести на стенд → подтвердить результат.', 'Практическое руководство', [
    section('start', 'Работайте в привычном редакторе', p('Экспорт E365 даёт доступ к описанию конфигурации: полям, формам, скриптам и связям. Оригинальный пакет сохраните отдельно. Для человека и AI-агента действует один цикл проверки; использование AI не является условием разработки.') + code('elma365pm unpack --src=example.e365 --out=workspace\nnode tools/workbench.mjs check workspace') + p(`Первую команду предоставляет официальная утилита, вторую — этот репозиторий. Нужен Node.js 22+. ${official}. Экспериментальная реструктуризация здесь не поддерживается: начните со стандартных сервисных каталогов.`)),
    section('route', 'Выберите задачу', `<ul><li>${link('package-map', 'Как устроен пакет и где менять исходник')}</li><li>${link('field-form-recipe', 'Добавить поле и показать его на форме')}</li><li>${link('relationship-recipe', 'Найти связи и использования')}</li><li>${link('script-roundtrip', 'Изменить скрипт и проверить runtime')}</li><li>${link('workbench', 'Работать в VS Code')}</li><li>${link('compatibility-lab', 'Проверить совместимость и результат импорта')}</li></ul>`),
    section('status', 'Что означает статус рецепта', p('«Локально проверено» означает проверку на синтетических объектах. «Подтверждено испытанием проекта» относится к конкретным CLI, платформе и операции. «Экспериментально» означает, что импорт и поведение на сервере ещё не доказаны. Зелёный JSON-check не подтверждает исполнение формы, права и миграцию данных.') + note('Структурные изменения экспериментальны', 'Новый STRING и строка формы создаются как черновик. В этом проекте не проведён серверный импорт данного рецепта.')),
    section('tools', 'Один набор правил для разных интерфейсов', p('Общий модуль extensions/e365-workbench/core.mjs используется CLI, учебным рецептом и расширением. Он не исполняет код конфигурации. Вики объясняет изменения и показывает индекс. Полный анализ процессов, поддержка новых схем и MCP-адаптер остаются следующим этапом.'))
  ], ['extensions/e365-workbench/core.mjs', 'tools/workbench.mjs', pm]),
  doc('package-map', 'Карта пакета E365', 'Физические пути, логическое дерево и части конфигурации, которые нужно сохранять.', 'Структура формата', [
    section('container', 'От архива к исходникам', p('E365 может содержать сервисные архивы. Для редактирования распакуйте его через elma365pm. package.json описывает пакет и его зависимости; service/manifest.json описывает сущности, ресурсы и историю. Не заменяйте полный экспорт только теми файлами, которые видны в индексе.')),
    section('paths', 'Файлы на примере учебного приложения', code('appViews/entities/example_module/requests.json\nwidgets/entities/example_module.requests/edit_form\nwidgets/entities/example_module.requests/edit_form.client.ts\nwidgets/entities/example_module.requests/edit_form.server.ts\nwidgets/manifest.json\npackage.json') + p('Первый файл содержит fields приложения. Второй — JSON формы, часто без расширения: descriptor.template, descriptor.fields, описание скриптов и runtime. Файлы .client.ts/.server.ts — отдельные исходники. Наш каталог examples/e365 содержит только синтетические фрагменты, без manifest/history; он не является пакетом для импорта.')),
    section('tree', 'Логическое дерево не перемещает файлы', p('Вики группирует объекты по решению, namespace и сервису. Workbench строит дерево поверх распакованного каталога. Физические пути остаются исходными; неизвестные свойства, ресурсы и файлы нужно сохранять при подготовке полного пакета. Не переносите объект между namespace только ради удобства редактора.')),
    section('types', 'JSON Schema и межфайловые связи', p('JSON Schema полезна для подсказок по изученным ключам. Ссылку из формы на поле другого файла одной локальной схемой не проверить: для этого используется анализатор. Сейчас Workbench понимает стандартные appViews/widgets/processor/entities, простые привязки item и текстовые Context/ViewContext.data. Другие схемы и процессы требуют отдельной проверки.') + p(`${official}. ${link('relationship-recipe', 'Проверка связей')}`))
  ], ['lib/e365.mjs', 'examples/e365/README.md', pm]),
  doc('field-form-recipe', 'Рецепт: поле и элемент формы', 'Создать согласованный локальный черновик из простого STRING-поля и строки формы.', 'Экспериментально · импорт не испытан', [
    section('two', 'Два независимых изменения', p('Добавление fields приложения создаёт описание данных. Отображение на форме находится в descriptor.template, во вложенных массивах content. Обязательность поля и обязательность элемента формы задаются отдельно: в учебном приложении title.required=false, а у строки формы required=true.') + code('{\n  "descriptor": "dynamic-form-row",\n  "values": {\n    "control": { "path": ["item", "title"] },\n    "required": true,\n    "showDisplayName": true\n  }\n}')),
    section('run', 'Создайте кандидаты без перезаписи экспорта', code('node tools/workbench.mjs add-field \\\n  examples/e365/appViews/entities/example_module/requests.json \\\n  examples/e365/widgets/entities/example_module.requests/edit_form \\\n  title integration_note "Комментарий интеграции" .local/candidate') + p('Перед запуском создайте .local; папка candidate должна отсутствовать. Команда создаёт app.candidate.json, form.candidate.json и review.json. Исходные файлы сохраняются. Рецепт находит единственную привязку, проверяет принадлежность формы приложению и генерирует новый UUID.')),
    section('code', 'Смысл правки в JavaScript', code('import { addStringField } from "./extensions/e365-workbench/core.mjs";\n\nconst candidate = addStringField({\n  app, form, sourceCode: "title",\n  code: "integration_note", name: "Комментарий интеграции"\n});\n// candidate.app.fields: новое STRING-поле\n// candidate.form: новая строка с path ["item", "integration_note"]\n// candidate.importReady === false') + p('Рецепт намеренно поддерживает простой STRING и простую dynamic-form-row. Системные, вычисляемые, массивные поля, defaultValue, дополнительные настройки и события отклоняются. Существующие неизвестные свойства сохраняются. Для сложного компонента изучите его контракт и напишите отдельный рецепт.')),
    section('review', 'От черновика к испытанию', note('Это не пакет импорта', 'Согласуйте manifest/history именно для структурного изменения; компиляция скриптов не доказывает правильность истории приложения. Пересоберите затронутые типы и runtime, проверьте ссылки процессов и права. На отдельном стенде сравните повторный экспорт, откройте форму и сохраните запись. До этого рецепт остаётся экспериментальным.') + p('Изменение required на форме само по себе не доказывает ограничение на серверных API. Удаление и переименование требуют миграции данных; нельзя считать удаление поля из JSON завершённой миграцией.'))
  ], ['tools/workbench.mjs', 'extensions/e365-workbench/core.mjs', 'test/workbench.test.mjs', exchange]),
  doc('relationship-recipe', 'Рецепт: связи и использования', 'От поля приложения к привязке формы, скрипту и зависимому решению.', 'Локально проверено · ограниченный анализ', [
    section('reference', 'Ссылка на другое приложение', code('{\n  "code": "category", "type": "SYS_COLLECTION",\n  "array": true, "single": true,\n  "data": {\n    "namespace": "example_module", "code": "categories",\n    "isDependent": false, "linkedFieldCode": ""\n  }\n}') + p('namespace/code идентифицируют приложение-цель. array и single могут сосуществовать: интерпретируйте их по контракту SDK и проверенному поведению платформы, а не по обычному правилу JavaScript «массив против скаляра».')),
    section('context', 'Данные приложения и состояние формы', code('async function onOpen(): Promise<void> {\n  const category = await Context.data.category?.fetch();\n  ViewContext.data.ready = Boolean(category);\n}') + p('Учебная вариация для связанной формы. Context задаётся привязкой к приложению; ViewContext — собственными полями формы. Проверьте, что category — подходящая одиночная ссылка по фактическому SDK, и привяжите onOpen к событию. Добавленная функция без привязки не вызовется. Этот фрагмент не прошёл отдельного серверного испытания.')),
    section('uses', 'Где используется поле?', code('node tools/workbench.mjs check examples/e365') + p('Результат содержит usages: файл, имя поля, owner и тип связи. Структурные привязки формы отмечены structural; обращения в скрипте — textual. В VS Code используйте F12 и «Найти все ссылки» на коде поля. Для переименования также исследуйте условия процессов, права, интеграции, Context.data[fieldName] и внешние пакеты: первая версия не строит их полный граф.')),
    section('missing', 'Отсутствует или не найдено?', p('Если связанное приложение есть в том же пакете, но поля в нём нет, Workbench выдаёт ошибку. Если приложение не разрешается однозначно, он выдаёт предупреждение: цель может находиться в зависимости или быть контекстом процесса. Вики дополнительно разрешает объявленные package-зависимости по загруженным решениям одного окружения. Не смешивайте снимки разных серверов.') + p('Поиск в TypeScript в первой версии текстовый: возможны совпадения в строках и комментариях; динамические обращения не учитываются. Это не безопасный автоматический refactoring.'))
  ], ['extensions/e365-workbench/core.mjs', 'lib/e365.mjs', exchange]),
  doc('script-roundtrip', 'Рецепт: скрипт → runtime → импорт', 'Что нужно синхронизировать, чтобы исполнялся именно изменённый исходник.', 'Подтверждено испытанием проекта · версии ограничены', [
    section('evidence', 'Условия проверенного цикла', p('Runbook проекта от 6 октября 2026 года описывает скриптовый round trip: elma365pm 1.19.0, целевой сервер 2026.7.23, решение установлено (isAuthor=false). Отчёт от 5 октября сравнивает локальный компилятор с серверным на 74 виджетах. Это результаты проекта, а не обещание совместимости со всеми версиями. Компилятор использует TypeScript 5.9.3 и типы, полученные от конкретного сервера.')),
    section('edit', 'Редактируйте соседние .ts', p('В исследованной связке CLI использовал .client.ts/.server.ts как источник импорта. Сервер сохранял переданный runtime без перекомпиляции. Следовательно, изменение только descriptor.*Scripts или только .ts недостаточно. Новая функция также должна иметь привязку к событию или вызову.') + code('// widgets/entities/example_module.requests/edit_form.client.ts\nasync function onOpen(): Promise<void> {\n  ViewContext.data.ready = Boolean(Context.data.title);\n}')),
    section('compile', 'Компиляция и review', code('# В checkout инструмента elma-dev; это не CLI Wiki\nnode bin/elma-dev.mjs compile --write --cross-check \\\n  --host https://target.example.com /path/to/export\nnode bin/elma-dev.mjs compile --verify --offline /path/to/export\ngit diff -- /path/to/export') + p('compile --write проверяет типы, регенерирует runtime, синхронизирует descriptor со скриптами и добавляет запись history виджета. Без новой истории импорт в испытаниях мог завершаться успешно без применения. --offline требует ранее полученного кеша типов для соответствующего host; отсутствие кеша — ошибка. --verify не меняет файлы. --no-check не равно проверке конструктора.')),
    section('transfer', 'Проверка пакета, перенос и доказательство', p('Разделяйте проверку структуры, компиляцию, проверку пригодности пакета и перенос. На сервере-авторе в испытаниях импорт формы встречал collision; цикл подтверждён для сервера установки. Следуйте runbook своей версии и проверяйте target явно.') + p('После обычного импорта повторно экспортируйте решение. Сравните исходники, descriptor, runtime и history; затем проверьте обработчик, RPC и права в форме. Exit 0 подтверждает завершение команды, но сам по себе не доказывает применение.') + p(`${official}. ${link('compatibility-lab', 'Матрица и протокол испытания')}`))
  ], ['elma-development/docs/file-based-widget-dev.md (2026-10-06)', 'docs/elma365-widget-compiler-2026-10-05.md', 'Исследование: netbka/elma365 @ 519b8c5462cc8b49caa6d1bd141873c7d14f835b', pm]),
  doc('workbench', 'E365 Workbench для VS Code', 'Первая версия расширения поверх исходных файлов; общие правила с CLI.', 'Реализовано v0.1 · требуется проверка в Extension Host', [
    section('install', 'Установка и запуск', code('npm ci\nnode tools/package-workbench.mjs\ncode --install-extension .local/e365-workbench-0.1.0.vsix') + p('Откройте распакованный экспорт как папку VS Code. В Explorer появится E365 Workbench. Расширение работает в доверенном workspace. Альтернатива для разработки: code --extensionDevelopmentPath=./extensions/e365-workbench examples/e365. Минимальная версия VS Code — 1.90.')),
    section('features', 'Что работает в первой версии', `<ul><li>Дерево: workspace → сервис → namespace → объект → поля и .ts.</li><li>F12 к определению поля из однозначной привязки или обращения.</li><li>«Найти все ссылки» и команда «Где используется поле?».</li><li>Диагностика JSON, повторных кодов полей и отсутствующих полей связанного приложения.</li><li>Команда проверки runtime через выбранный локальный elma-dev: compile --verify --offline --host &lt;адрес сервера кеша&gt;.</li></ul>` + p('Обновление происходит после сохранения и по команде E365: Обновить индекс. Изменения файлов вне редактора требуют ручного обновления. ZIP/E365 предварительно распакуйте. Навигация работает и для extensionless JSON; имя файла берётся из стандартного каталога entities.')),
    section('limits', 'Границы первой версии', p('Процессные контексты индексируются, но их привязки к формам полностью не разрешаются. Manifest/history не валидируются. Поиск в .ts текстовый и может находить строки/комментарии. Подсветка диапазона в JSON использует первое вхождение кода; при повторении требуется проверка. Нет автоматического переименования, визуального редактора формы, импорта и исполнения пользовательских скриптов.') + p('Тесты общего модуля и упаковки не заменяют проверку VS Code Extension Host. Лимиты индекса: 25 000 записей дерева, 4 МБ на файл и 64 МБ прочитанного содержимого; symlink не обходятся.')),
    section('next', 'Как развивать IDE', p('Следующие этапы: версионная модель manifest и dependencies, AST для TypeScript и динамических обращений, мастер полей с diff и протоколом миграции, затем Custom Editor для предпросмотра формы. Визуальный предпросмотр не эмулирует серверные права, RPC и процессы. MCP-адаптер может использовать тот же core; пока он не реализован.') + p('<a href="https://code.visualstudio.com/api/extension-guides/tree-view" rel="noreferrer">VS Code Tree View API</a> · <a href="https://code.visualstudio.com/api/extension-guides/custom-editors" rel="noreferrer">Custom Editor API</a>'))
  ], ['extensions/e365-workbench/extension.cjs', 'extensions/e365-workbench/core.mjs', 'tools/package-workbench.mjs']),
  doc('compatibility-lab', 'Лаборатория совместимости', 'Разделяйте подтверждённый перенос скрипта и экспериментальные изменения схемы.', 'Матрица испытаний · 6 октября 2026', [
    section('matrix', 'Матрица подтверждений', `<div class="table-wrap"><table><thead><tr><th>Сценарий</th><th>Версии / среда</th><th>Статус</th></tr></thead><tbody><tr><td>Скрипт, runtime, history, импорт и повторный экспорт</td><td>CLI 1.19.0 / сервер 2026.7.23 / isAuthor=false</td><td>Подтверждено runbook проекта</td></tr><tr><td>Сравнение компиляторов на 74 виджетах</td><td>TypeScript 5.9.3 / серверы 2025.4.55 и 2026.7.23</td><td>Подтверждено отчётом проекта; есть ограничения endpoint</td></tr><tr><td>Импорт формы на сервер-автор</td><td>Изученные серверы / isAuthor=true</td><td>Наблюдался collision</td></tr><tr><td>Добавление поля и элемента формы</td><td>Синтетические JSON / локальные тесты</td><td>Экспериментально, серверный импорт не испытан</td></tr><tr><td>Другая версия или схема</td><td>Не определена</td><td>Требуется отдельное испытание</td></tr></tbody></table></div>`),
    section('protocol', 'Воспроизводимый протокол', `<ol><li>Запишите версии CLI, платформы, роль сервера (автор/установка), code решения и hash исходного экспорта.</li><li>Сделайте одну правку; сохраните diff и ожидаемый результат.</li><li>Зафиксируйте вывод структурных проверок, компилятора и проверки пакета.</li><li>Перенесите на отдельный стенд штатным способом; запишите результат.</li><li>Повторно экспортируйте и сравните конкретные поля JSON, runtime и историю.</li><li>Откройте форму, вызовите обработчик и проверьте сохранение записи с нужной ролью.</li><li>Зафиксируйте восстановление исходного состояния и оставшиеся ограничения.</li></ol>`),
    section('contradiction', 'Почему версии обязательны', p('Старые материалы о side-файлах как копиях для чтения расходятся с испытанием CLI 1.19.0. Поведение импорта и компиляции нельзя переносить на все поставки. Серверный endpoint Проверить в отчёте имел ограничения для новых RPC-функций и импортированных форм. Для нового сочетания версий повторите минимальный опыт, а не меняйте статус рецепта по аналогии.')),
    section('migration', 'Изменение структуры и миграция', p('Проверьте отдельно добавление, удаление, переименование, обязательность и тип поля. Исчезнувший объект из JSON не обязательно удаляется на целевой стороне. План миграции данных, зависимости пакетов и восстановление не заменяются упаковкой файла.') + p(`<a href="${exchange}" rel="noreferrer">Официальные правила экспорта и импорта</a>. Локальные примеры этого портала синтетические и не содержат частных конфигураций.`))
  ], ['elma-development/docs/file-based-widget-dev.md (2026-10-06)', 'docs/elma365-widget-compiler-2026-10-05.md', exchange])
];
